use genewars_runtime::{building_power::*,landing::*,actor_activation::TrigTables};use std::{fs,path::PathBuf};
fn main(){let p=PathBuf::from(std::env::args().nth(1).unwrap());let input=fs::read(p.join("input.bin")).unwrap();let trig=TrigTables::generate_pinned().unwrap();let mut out=Vec::new();for (case,c)in input.chunks_exact(96).enumerate(){let prior=c[..81].try_into().unwrap();let code=c[81];let slot=c[82]as usize;let angles=std::array::from_fn(|i|u16::from_le_bytes(c[83+i*2..85+i*2].try_into().unwrap()));let rng=LandingRng{seed:u16::from_le_bytes(c[89..91].try_into().unwrap()),ring:c[91],draw_count:u32::from_le_bytes(c[92..96].try_into().unwrap())};let mut pool=[[0;81];200];for b in &mut pool[..slot]{b[6]=5}pool[slot]=prior;
let (a,r)=if code==33{let request=PowerTransfer33Request{destination:[7,0,4],source_position:[20864,13696],destination_position:[0,0],payload:case as u8,yaw:angles[0],pitch:512,speed:2048,height_above_ground:512};(plan_transfer_factory(&pool,slot as i16,&request,6272,0,None,&trig).unwrap().after_nonpointer,rng)}else{let q=plan_landing_effect6_factory(&pool,slot as i16,[20864,13696],6272,0,6784,angles,None,1024,rng,trig.sine().try_into().unwrap(),trig.cosine().try_into().unwrap()).unwrap();(q.factory.after_nonpointer,q.rng_after)};out.extend(a);out.extend(r.seed.to_le_bytes());out.push(r.ring);out.extend(r.draw_count.to_le_bytes());}fs::write(p.join("actual.bin"),out).unwrap();}

